import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

interface ProfileData {
  name: string;
  phone: string;
  bankAccount: string;
  bankIFSC: string;
  kycStatus: string;
  referralCode: string;
  rank: string;
}

const Settings: React.FC = () => {
  const [profile, setProfile] = useState<ProfileData>({
    name: '',
    phone: '',
    bankAccount: '',
    bankIFSC: '',
    kycStatus: 'pending',
    referralCode: '',
    rank: '',
  });
  const [loading, setLoading] = useState(false);
  const [copying, setCopying] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const distributorId = localStorage.getItem('distributorId') || '';
        const response = await api.get(`/distributors/${distributorId}`);
        setProfile({
          name: response.data.name || '',
          phone: response.data.phone || '',
          bankAccount: response.data.bankAccount || '',
          bankIFSC: response.data.bankIFSC || '',
          kycStatus: response.data.kycVerified ? 'verified' : 'pending',
          referralCode: response.data.referralCode || '',
          rank: response.data.rank || '',
        });
      } catch (error) {
        console.error('Failed to fetch profile', error);
      }
    };
    fetchProfile();
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setProfile({
      ...profile,
      [e.target.name]: e.target.value,
    });
  };

  const handleSave = async () => {
    setLoading(true);
    try {
      const distributorId = localStorage.getItem('distributorId') || '';
      await api.updateProfile(distributorId, {
        name: profile.name,
        phone: profile.phone,
        bankAccount: profile.bankAccount,
        bankIFSC: profile.bankIFSC,
      });
      alert('Profile updated successfully!');
    } catch (error: any) {
      console.error('Update error:', error);
      alert(error.response?.data?.message || 'Update failed');
    } finally {
      setLoading(false);
    }
  };

  const copyReferralCode = async () => {
    setCopying(true);
    try {
      await navigator.clipboard.writeText(profile.referralCode);
      alert('Referral code copied to clipboard!');
    } catch (error) {
      alert('Failed to copy referral code');
    } finally {
      setCopying(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('access_token');
    localStorage.removeItem('distributorId');
    navigate('/login');
  };

  return (
    <div className="space-y-6">
      <h1 className="text-3xl font-bold text-gray-800">Settings</h1>

      <div className="card bg-gradient-to-r from-green-50 to-emerald-50 border-2 border-green-200">
        <h2 className="text-xl font-bold mb-4 text-green-700">🎯 Your Referral Code (Your Phone Number)</h2>
        <p className="text-gray-600 mb-3">Your phone number is your unique referral code. Share it with others to earn commissions on their purchases when they join your network using this code.</p>
        <div className="flex items-center gap-3 bg-white p-4 rounded-lg border-2 border-green-300">
          <code className="text-2xl font-bold text-green-600 flex-1">{profile.referralCode}</code>
          <button
            onClick={copyReferralCode}
            disabled={copying}
            className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition font-semibold"
          >
            {copying ? 'Copying...' : 'Copy'}
          </button>
        </div>
        <div className="bg-blue-50 border-l-4 border-blue-400 p-3 mt-3 rounded">
          <p className="text-sm text-blue-700"><strong>💡 How to share:</strong> Give your phone number to your referrals. They can use it when registering as the "Sponsor's Phone" field.</p>
        </div>
      </div>

      <div className="card">
        <h2 className="text-xl font-bold mb-4">Profile Information</h2>
        <div className="space-y-4">
          <div>
            <label className="block text-gray-700 mb-2">Current Rank</label>
            <input
              type="text"
              disabled
              className="input-field bg-gray-100 cursor-not-allowed"
              value={profile.rank}
            />
          </div>

          <div>
            <label className="block text-gray-700 mb-2">Full Name</label>
            <input
              type="text"
              name="name"
              className="input-field"
              value={profile.name}
              onChange={handleChange}
            />
          </div>

          <div>
            <label className="block text-gray-700 mb-2">Phone</label>
            <input
              type="tel"
              name="phone"
              className="input-field"
              value={profile.phone}
              onChange={handleChange}
            />
          </div>

          <div>
            <label className="block text-gray-700 mb-2">Bank Account</label>
            <input
              type="text"
              name="bankAccount"
              className="input-field"
              value={profile.bankAccount}
              onChange={handleChange}
            />
          </div>

          <div>
            <label className="block text-gray-700 mb-2">Bank IFSC</label>
            <input
              type="text"
              name="bankIFSC"
              className="input-field"
              value={profile.bankIFSC}
              onChange={handleChange}
            />
          </div>

          <button onClick={handleSave} className="btn-primary w-full" disabled={loading}>
            {loading ? 'Saving...' : 'Save Changes'}
          </button>
        </div>
      </div>

      <div className="card">
        <h2 className="text-xl font-bold mb-4">KYC Status</h2>
        <p className="text-gray-600 mb-4">Current Status: <span className={`font-bold ${profile.kycStatus === 'verified' ? 'text-green-600' : 'text-yellow-600'}`}>{profile.kycStatus === 'verified' ? 'Verified ✓' : 'Pending'}</span></p>
        <button className="btn-primary w-full">Upload KYC Documents</button>
      </div>

      <div className="card">
        <h2 className="text-xl font-bold mb-4">Danger Zone</h2>
        <button onClick={handleLogout} className="w-full px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition">
          Logout
        </button>
      </div>
    </div>
  );
};

export default Settings;
